  /// < Interrupted by a resource conflict (Since 5.0)
  static const int MEDIACODEC_ERROR_RESOURCE_CONFLICT = -26935281;
}

/// @brief Enumeration of buffer status.
/// @since_tizen @if MOBILE 2.4 @elseif WEARABLE 3.0 @endif
